def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_m, last_o = history[-1]
    opp_defects = sum(1 for _, o in history if o == 'D')

    if last_o == 'C':
        if n >= 15 and opp_defects * 100 >= n * 50:
            start = n - 12
            if start < 1:
                start = 1

            recent_opp_d = 0
            recent_unprov = 0
            recent_prev_c = 0

            for i in range(start, n):
                if history[i][1] == 'D':
                    recent_opp_d += 1
                if history[i-1][0] == 'C':
                    recent_prev_c += 1
                    if history[i][1] == 'D':
                        recent_unprov += 1

            if (
                recent_opp_d >= 7
                and recent_unprov >= 4
                and recent_prev_c > 0
                and recent_unprov * 2 >= recent_prev_c
            ):
                return 'D'

        return 'C'

    if n < 10:
        return 'D'

    if n > 90 and opp_defects <= 2:
        return 'C'

    if n < 30:
        if opp_defects <= max(1, n // 10):
            return 'C'
        return 'D'

    if opp_defects > n * 0.3:
        return 'D'

    if opp_defects > n * 0.15:
        if last_m == 'D' and n >= 2 and history[-2][1] == 'D':
            return 'C'
        return 'D'

    return 'C'
